//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
)

func TestEnum_WIFI_CONFIG_AP_RESPONSE(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.WIFI_CONFIG_AP_RESPONSE
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.WIFI_CONFIG_AP_RESPONSE_UNDEFINED.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.WIFI_CONFIG_AP_RESPONSE
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.WIFI_CONFIG_AP_RESPONSE_UNDEFINED, dec)
	})
}
